package fr.bbodin.courbedepoids;
import android.content.ContentValues;import android.content.Context;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import android.database.sqlite.SQLiteOpenHelper;import org.json.JSONObject;import java.util.ArrayList;import java.util.HashSet;import java.util.List;import java.util.Set;
public class WeightDatabase extends SQLiteOpenHelper{
 private static final String DB_NAME="logging.db";private static final int DB_VERSION=1;private static final String GENERIC_TABLE="generic_events";private final Context context;
 public static class GenericEvent{public final long id;public final String typeId,date,payload;public final long createdAt;public GenericEvent(long id,String typeId,String date,long createdAt,String payload){this.id=id;this.typeId=typeId;this.date=date;this.createdAt=createdAt;this.payload=payload;}}
 public WeightDatabase(Context context){super(context,DB_NAME,null,DB_VERSION);this.context=context.getApplicationContext();}
 @Override public void onCreate(SQLiteDatabase db){createGenericEventsTable(db);}
  private void createGenericEventsTable(SQLiteDatabase db){db.execSQL("CREATE TABLE IF NOT EXISTS "+GENERIC_TABLE+" (_id INTEGER PRIMARY KEY AUTOINCREMENT, type_id TEXT NOT NULL, date TEXT NOT NULL, created_at INTEGER NOT NULL, payload TEXT NOT NULL)");db.execSQL("CREATE INDEX IF NOT EXISTS idx_generic_events_date ON "+GENERIC_TABLE+" (date, created_at)");db.execSQL("CREATE INDEX IF NOT EXISTS idx_generic_events_type ON "+GENERIC_TABLE+" (type_id)");}
 static boolean isValidGenericEvent(String typeId,String date,long createdAt,String payload){
  if(!LoggingTypeRegistry.isValidTypeId(typeId)||date==null||!date.matches("\\d{4}-\\d{2}-\\d{2}")||createdAt<0||payload==null)return false;
  try{JSONObject p=new JSONObject(payload);if("weight".equals(typeId)){double v=p.optDouble("weight_kg",Double.NaN);return Double.isFinite(v)&&v>0&&v<=500;}if("water".equals(typeId)){int v=p.optInt("amount_ml",-1);return v>=1&&v<=10000;}if("sport".equals(typeId)){String a=p.optString("activity","");int d=p.optInt("duration_minutes",-1);double k=p.optDouble("distance_km",0);boolean valid=a.equals("Yoga")||a.equals("Course")||a.equals("Escalade")||a.equals("Workout");return valid&&d>=1&&d<=1440&&Double.isFinite(k)&&k>=0&&k<=1000&&(a.equals("Course")||k==0);}return true;}catch(Exception e){return false;}
 }
 public long saveGenericEvent(String typeId,String date,long createdAt,String payload){if(!isValidGenericEvent(typeId,date,createdAt,payload))throw new IllegalArgumentException("Invalid generic event");SQLiteDatabase db=getWritableDatabase();if("weight".equals(typeId))db.delete(GENERIC_TABLE,"type_id=? AND date=?",new String[]{typeId,date});ContentValues v=new ContentValues();v.put("type_id",typeId);v.put("date",date);v.put("created_at",createdAt);v.put("payload",payload);long id=db.insertOrThrow(GENERIC_TABLE,null,v);AutoBackupScheduler.backupIfEnabled(context);return id;}
 public void updateGenericEvent(long id,String typeId,String date,long createdAt,String payload){if(!isValidGenericEvent(typeId,date,createdAt,payload))throw new IllegalArgumentException("Invalid generic event");SQLiteDatabase db=getWritableDatabase();if("weight".equals(typeId)){Cursor c=db.query(GENERIC_TABLE,new String[]{"_id"},"type_id=? AND date=? AND _id<>?",new String[]{typeId,date,String.valueOf(id)},null,null,null);try{if(c.moveToFirst())throw new IllegalArgumentException("Une mesure de poids existe déjà pour cette date.");}finally{c.close();}}ContentValues v=new ContentValues();v.put("type_id",typeId);v.put("date",date);v.put("created_at",createdAt);v.put("payload",payload);if(db.update(GENERIC_TABLE,v,"_id=? AND type_id=?",new String[]{String.valueOf(id),typeId})==0)throw new IllegalArgumentException("Generic event not found");AutoBackupScheduler.backupIfEnabled(context);}
 public List<GenericEvent> allGenericEvents(){List<GenericEvent> out=new ArrayList<>();Cursor c=getReadableDatabase().query(GENERIC_TABLE,new String[]{"_id","type_id","date","created_at","payload"},null,null,null,null,"date DESC, created_at DESC, _id DESC");try{while(c.moveToNext())out.add(new GenericEvent(c.getLong(0),c.getString(1),c.getString(2),c.getLong(3),c.getString(4)));}finally{c.close();}return out;}
 public GenericEvent getGenericEvent(long id,String typeId){Cursor c=getReadableDatabase().query(GENERIC_TABLE,new String[]{"_id","type_id","date","created_at","payload"},"_id=? AND type_id=?",new String[]{String.valueOf(id),typeId},null,null,null);try{return c.moveToFirst()?new GenericEvent(c.getLong(0),c.getString(1),c.getString(2),c.getLong(3),c.getString(4)):null;}finally{c.close();}}
 public void replaceGenericEvents(List<GenericEvent> events){SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{db.delete(GENERIC_TABLE,null,null);Set<String> dates=new HashSet<>();for(GenericEvent e:events){if(e==null||!isValidGenericEvent(e.typeId,e.date,e.createdAt,e.payload))throw new IllegalArgumentException("Invalid generic event");if("weight".equals(e.typeId)&&!dates.add(e.date))throw new IllegalArgumentException("Une mesure de poids existe déjà pour cette date.");ContentValues v=new ContentValues();v.put("type_id",e.typeId);v.put("date",e.date);v.put("created_at",e.createdAt);v.put("payload",e.payload);db.insertOrThrow(GENERIC_TABLE,null,v);}db.setTransactionSuccessful();}finally{db.endTransaction();}AutoBackupScheduler.backupIfEnabled(context);}
 public void deleteEvent(String typeId,String eventId){if(typeId==null||eventId==null||eventId.trim().isEmpty())throw new IllegalArgumentException("Event type and ID are required");int count=getWritableDatabase().delete(GENERIC_TABLE,"type_id=? AND _id=?",new String[]{typeId,eventId});if(count>0)AutoBackupScheduler.backupIfEnabled(context);}
}
